  match body with
  | Children v ->
      (match v with
      | Seq [v0; v1; v2; v3; v4; v5] ->
          (
            Run.trans_token (Run.matcher_token v0),
            Run.trans_token (Run.matcher_token v1),
            trans_expression (Run.matcher_token v2),
            Run.trans_token (Run.matcher_token v3),
            trans_type_descriptor (Run.matcher_token v4),
            Run.trans_token (Run.matcher_token v5)
          )
      | _ -> assert false
      )
  | Leaf _ -> assert false

and trans_while_statement ((kind, body) : mt) : CST.while_statement =
  match body with
  | Children v ->
      (match v with
      | Seq [v0; v1; v2] ->
          (
            Run.trans_token (Run.matcher_token v0),
            trans_parenthesized_expression (Run.matcher_token v1),
            trans_statement (Run.matcher_token v2)
          )
      | _ -> assert false
      )
  | Leaf _ -> assert false





let trans_semgrep_expression ((kind, body) : mt) : CST.semgrep_expression =
  match body with
  | Children v ->
      (match v with
      | Seq [v0; v1] ->
          (
            Run.trans_token (Run.matcher_token v0),
            trans_expression (Run.matcher_token v1)
          )
      | _ -> assert false
      )
  | Leaf _ -> assert false
















let trans_top_level_expression_statement ((kind, body) : mt) : CST.top_level_expression_statement =
  match body with
  | Children v ->
      (match v with
      | Seq [v0; v1] ->
          (
            Run.opt
              (fun v ->
                (match v with
                | Alt (0, v) ->
                    `Choice_cond_exp (
                      (match v with
                      | Alt (0, v) ->
                          `Cond_exp (
                            trans_conditional_expression (Run.matcher_token v)
                          )
                      | Alt (1, v) ->
                          `Assign_exp (
                            trans_assignment_expression (Run.matcher_token v)
                          )
                      | Alt (2, v) ->
                          `Un_exp (
                            trans_unary_expression (Run.matcher_token v)
                          )
                      | Alt (3, v) ->
                          `Update_exp (
                            trans_update_expression (Run.matcher_token v)
                          )
                      | Alt (4, v) ->
                          `Cast_exp (
                            trans_cast_expression (Run.matcher_token v)
                          )
                      | Alt (5, v) ->
                          `Poin_exp (
                            trans_pointer_expression (Run.matcher_token v)
                          )
                      | Alt (6, v) ->
                          `Sizeof_exp (
                            trans_sizeof_expression (Run.matcher_token v)
                          )
                      | Alt (7, v) ->
                          `Alig_exp (
                            trans_alignof_expression (Run.matcher_token v)
                          )
                      | Alt (8, v) ->
                          `Offs_exp (
                            trans_offsetof_expression (Run.matcher_token v)
                          )
                      | Alt (9, v) ->
                          `Gene_exp (
                            trans_generic_expression (Run.matcher_token v)
                          )
                      | Alt (10, v) ->
                          `Subs_exp (
                            trans_subscript_expression (Run.matcher_token v)
                          )
                      | Alt (11, v) ->
                          `Call_exp (
                            trans_call_expression (Run.matcher_token v)
                          )
                      | Alt (12, v) ->
                          `Field_exp (
                            trans_field_expression (Run.matcher_token v)
                          )
                      | Alt (13, v) ->
                          `Comp_lit_exp (
                            trans_compound_literal_expression (Run.matcher_token v)
                          )
                      | Alt (14, v) ->
                          `Id (
                            trans_identifier (Run.matcher_token v)
                          )
                      | Alt (15, v) ->
                          `Num_lit (
                            trans_number_literal (Run.matcher_token v)
                          )
                      | Alt (16, v) ->
                          `Str (
                            trans_string_ (Run.matcher_token v)
                          )
                      | Alt (17, v) ->
                          `True (
                            trans_true_ (Run.matcher_token v)
                          )
                      | Alt (18, v) ->
                          `False (
                            trans_false_ (Run.matcher_token v)
                          )
                      | Alt (19, v) ->
                          `Null (
                            trans_null (Run.matcher_token v)
                          )
                      | Alt (20, v) ->
                          `Char_lit (
                            trans_char_literal (Run.matcher_token v)
                          )
                      | Alt (21, v) ->
                          `Paren_exp (
                            trans_parenthesized_expression (Run.matcher_token v)
                          )
                      | Alt (22, v) ->
                          `Gnu_asm_exp (
                            trans_gnu_asm_expression (Run.matcher_token v)
                          )
                      | Alt (23, v) ->
                          `Exte_exp (
                            trans_extension_expression (Run.matcher_token v)
                          )
                      | _ -> assert false
                      )
                    )
                | Alt (1, v) ->
                    `Mess_exp (
                      trans_message_expression (Run.matcher_token v)
                    )
                | Alt (2, v) ->
                    `Sele_exp (
                      trans_selector_expression (Run.matcher_token v)
                    )
                | Alt (3, v) ->
                    `Avai_exp (
                      trans_available_expression (Run.matcher_token v)
                    )
                | Alt (4, v) ->
                    `Range_exp (
                      trans_range_expression (Run.matcher_token v)
                    )
                | Alt (5, v) ->
                    `Blk_lit (
                      trans_block_literal (Run.matcher_token v)
                    )
                | Alt (6, v) ->
                    `Dict_lit (
                      trans_dictionary_literal (Run.matcher_token v)
                    )
                | Alt (7, v) ->
                    `Array_lit (
                      trans_array_literal (Run.matcher_token v)
                    )
                | Alt (8, v) ->
                    `At_exp (
                      trans_at_expression (Run.matcher_token v)
                    )
                | Alt (9, v) ->
                    `Encode_exp (
                      trans_encode_expression (Run.matcher_token v)
                    )
                | Alt (10, v) ->
                    `Va_arg_exp (
                      trans_va_arg_expression (Run.matcher_token v)
                    )
                | Alt (11, v) ->
                    `Choice_id (
                      (match v with
                      | Alt (0, v) ->
                          `Id (
                            Run.trans_token (Run.matcher_token v)
                          )
                      | Alt (1, v) ->
                          `In (
                            Run.trans_token (Run.matcher_token v)
                          )
                      | Alt (2, v) ->
                          `Struct (
                            Run.trans_token (Run.matcher_token v)
                          )
                      | Alt (3, v) ->
                          `Const (
                            Run.trans_token (Run.matcher_token v)
                          )
                      | _ -> assert false
                      )
                    )
                | _ -> assert false
                )
              )
              v0
            ,
            Run.trans_token (Run.matcher_token v1)
          )
      | _ -> assert false
      )
  | Leaf _ -> assert false








let trans_top_level_statement ((kind, body) : mt) : CST.top_level_statement =
  match body with
  | Children v ->
      (match v with
      | Alt (0, v) ->
          `Choice_case_stmt (
            (match v with
            | Alt (0, v) ->
                `Case_stmt (
                  trans_case_statement (Run.matcher_token v)
                )
            | Alt (1, v) ->
                `Attr_stmt (
                  trans_attributed_statement (Run.matcher_token v)
                )
            | Alt (2, v) ->
                `Labe_stmt (
                  trans_labeled_statement (Run.matcher_token v)
                )
            | Alt (3, v) ->
                `Comp_stmt (
                  trans_compound_statement (Run.matcher_token v)
                )
            | Alt (4, v) ->
                `Top_level_exp_stmt (
                  trans_top_level_expression_statement (Run.matcher_token v)
                )
            | Alt (5, v) ->
                `If_stmt (
                  trans_if_statement (Run.matcher_token v)
                )
            | Alt (6, v) ->
                `Switch_stmt (
                  trans_switch_statement (Run.matcher_token v)
                )
            | Alt (7, v) ->
                `Do_stmt (
                  trans_do_statement (Run.matcher_token v)
                )
            | Alt (8, v) ->
                `While_stmt (
                  trans_while_statement (Run.matcher_token v)
                )
            | Alt (9, v) ->
                `For_stmt (
                  trans_for_statement (Run.matcher_token v)
                )
            | Alt (10, v) ->
                `Ret_stmt (
                  trans_return_statement (Run.matcher_token v)
                )
            | Alt (11, v) ->
                `Brk_stmt (
                  trans_break_statement (Run.matcher_token v)
                )
            | Alt (12, v) ->
                `Cont_stmt (
                  trans_continue_statement (Run.matcher_token v)
                )
            | Alt (13, v) ->
                `Goto_stmt (
                  trans_goto_statement (Run.matcher_token v)
                )
            | _ -> assert false
            )
          )
      | Alt (1, v) ->
          `Semg_ellips (
            trans_semgrep_ellipsis (Run.matcher_token v)
          )
      | _ -> assert false
      )
  | Leaf _ -> assert false





let trans_top_level_item ((kind, body) : mt) : CST.top_level_item =
  match body with
  | Children v ->
      (match v with
      | Alt (0, v) ->
          `Choice_func_defi (
            (match v with
            | Alt (0, v) ->
                `Func_defi (
                  trans_function_definition (Run.matcher_token v)
                )
            | Alt (1, v) ->
                `Old_style_func_defi (
                  trans_old_style_function_definition (Run.matcher_token v)
                )
            | Alt (2, v) ->
                `Link_spec (
                  trans_linkage_specification (Run.matcher_token v)
                )
            | Alt (3, v) ->
                `Decl (
                  trans_declaration (Run.matcher_token v)
                )
            | Alt (4, v) ->
                `Top_level_stmt (
                  trans_top_level_statement (Run.matcher_token v)
                )
            | Alt (5, v) ->
                `Attr_stmt (
                  trans_attributed_statement (Run.matcher_token v)
                )
            | Alt (6, v) ->
                `Type_defi (
                  trans_type_definition (Run.matcher_token v)
                )
            | Alt (7, v) ->
                `Empty_decl (
                  trans_empty_declaration (Run.matcher_token v)
                )
            | Alt (8, v) ->
                `Prep_if (
                  trans_preproc_if (Run.matcher_token v)
                )
            | Alt (9, v) ->
                `Prep_ifdef (
                  trans_preproc_ifdef (Run.matcher_token v)
                )
            | Alt (10, v) ->
                `Prep_incl (
                  trans_preproc_include (Run.matcher_token v)
                )
            | Alt (11, v) ->
                `Prep_def (
                  trans_preproc_def (Run.matcher_token v)
                )
            | Alt (12, v) ->
                `Prep_func_def (
                  trans_preproc_function_def (Run.matcher_token v)
                )
            | Alt (13, v) ->
                `Prep_call (
                  trans_preproc_call (Run.matcher_token v)
                )
            | _ -> assert false
            )
          )
      | Alt (1, v) ->
          `Class_decl (
            trans_class_declaration (Run.matcher_token v)
          )
      | Alt (2, v) ->
          `Class_inte (
            trans_class_interface (Run.matcher_token v)
          )
      | Alt (3, v) ->
          `Class_impl (
            trans_class_implementation (Run.matcher_token v)
          )
      | Alt (4, v) ->
          `Prot_decl (
            trans_protocol_declaration (Run.matcher_token v)
          )
      | Alt (5, v) ->
          `Prot_forw_decl (
            trans_protocol_forward_declaration (Run.matcher_token v)
          )
      | Alt (6, v) ->
          `Module_import (
            trans_module_import (Run.matcher_token v)
          )
      | Alt (7, v) ->
          `Comp_alias_decl (
            trans_compatibility_alias_declaration (Run.matcher_token v)
          )
      | Alt (8, v) ->
          `Prep_undef (
            trans_preproc_undef (Run.matcher_token v)
          )
      | Alt (9, v) ->
          `Prep_line (
            trans_preproc_linemarker (Run.matcher_token v)
          )
      | _ -> assert false
      )
  | Leaf _ -> assert false

let trans_translation_unit ((kind, body) : mt) : CST.translation_unit =
  match body with
  | Children v ->
      (match v with
      | Alt (0, v) ->
          `Rep_top_level_item (
            Run.repeat
              (fun v -> trans_top_level_item (Run.matcher_token v))
              v
          )
      | Alt (1, v) ->
          `Semg_exp (
            trans_semgrep_expression (Run.matcher_token v)
          )
      | _ -> assert false
      )
  | Leaf _ -> assert false

(*
   Costly operation that translates a whole tree or subtree.

   The first pass translates it into a generic tree structure suitable
   to guess which node corresponds to each grammar rule.
   The second pass is a translation into a typed tree where each grammar
   node has its own type.

   This function is called:
   - once on the root of the program after removing extras
     (comments and other nodes that occur anywhere independently from
     the grammar);
   - once of each extra node, resulting in its own independent tree of type
     'extra'.
*)
let translate_tree src node trans_x =
  let matched_tree = Run.match_tree children_regexps src node in
  Option.map trans_x matched_tree


let translate_extra src (node : Tree_sitter_output_t.node) : CST.extra option =
  match node.type_ with
  | "comment" ->
      (match translate_tree src node trans_comment with
      | None -> None
      | Some x -> Some (`Comment (Run.get_loc node, x)))
  | _ -> None

let translate_root src root_node =
  translate_tree src root_node trans_translation_unit

let parse_input_tree input_tree =
  let orig_root_node = Tree_sitter_parsing.root input_tree in
  let src = Tree_sitter_parsing.src input_tree in
  let errors = Run.extract_errors src orig_root_node in
  let opt_program, extras =
     Run.translate
       ~extras
       ~translate_root:(translate_root src)
       ~translate_extra:(translate_extra src)
       orig_root_node
  in
  Parsing_result.create src opt_program extras errors

let string ?src_file contents =
  let input_tree = parse_source_string ?src_file contents in
  parse_input_tree input_tree

let file src_file =
  let input_tree = parse_source_file src_file in
  parse_input_tree input_tree

